import os,pathlib,subprocess,tempfile
def revoke_certificate(certificate,prior,output):
    certificate,prior,output=map(pathlib.Path,(certificate,prior,output))
    if any(p.is_symlink() or not p.is_file() for p in (certificate,prior)) or output.is_symlink():raise ValueError('regular owned inputs required')
    if output.resolve() in (certificate.resolve(),prior.resolve()):raise ValueError('distinct output required')
    fields=certificate.read_text().split()
    if not fields or fields[0]!='ssh-ed25519-cert-v01@openssh.com':raise ValueError('Ed25519 certificate required, not raw key or CA')
    check=subprocess.run(['ssh-keygen','-L','-f',str(certificate)],capture_output=True,text=True,timeout=3)
    if check.returncode:raise ValueError('invalid certificate')
    check=subprocess.run(['ssh-keygen','-Q','-f',str(prior),str(certificate)],capture_output=True,text=True,timeout=3)
    if check.returncode not in (0,1):raise ValueError('invalid prior KRL')
    fd,name=tempfile.mkstemp(prefix='.krl-',dir=output.parent)
    try:
        with os.fdopen(fd,'wb') as stream:stream.write(prior.read_bytes())
        result=subprocess.run(['ssh-keygen','-k','-u','-f',name,str(certificate)],capture_output=True,text=True,timeout=3)
        if result.returncode:raise ValueError('certificate revocation update failed')
        os.chmod(name,0o600);os.replace(name,output)
    finally:
        if os.path.exists(name):os.unlink(name)
